import type { SqlProblem } from '../problems'
import { idFor, moduleTopic } from './mapping'

// MIRROR's rebuild of part of the 300-question interview bank on the company tables (see docs/SQL-DB-SCHEMA.md).
// Dates are relative to the fixed snapshot 2025-12-31. Scenario text is practice data, not instructions.
const PT = {
  AJ: 'Anti-joins, EXISTS and missing data',
  SQ: 'Subqueries and comparing to an average',
  DS: 'Duplicates and set operations',
  CA: 'Conditional aggregation, pivots and percentages',
} as const
const LV = { B: 'Beginner', P: 'Pro', A: 'Advanced' } as const
const AS = { p: 'Phone screen', o: 'Onsite', t: 'Take-home' } as const

const Q = (n: number, k: keyof typeof PT, lv: keyof typeof LV, title: string, minutes: number, scenario: string, prompt: string, output: string,
  pattern: string, asked: keyof typeof AS, followUp: string, edgeCases: string[], tables: string[], hint: string, explain: string, solution: string): SqlProblem =>
  ({ id: idFor(n), ...moduleTopic(PT[k], LV[lv]), title, minutes, scenario, prompt, output, pattern, asked: AS[asked], followUp, edgeCases, tables, hint, explain, solution, ordered: true })

